BEGIN;

-- terraform-associate
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"terraform-associate-q1": {"point": "「コードで宣言的に定義」「再現性」「バージョン管理」「レビュー」という言葉が並んでいたらIaCの利点そのもの。監視の一元化や成果物の配布パイプラインの話にすり替わっていないか確認する。", "eg": "同じ楽譜があれば、誰が演奏しても同じ曲になるようなもの。楽譜(コード)が無いと、その場の勘(手作業)で演奏がばらつく。"}, "terraform-associate-q2": {"point": "「どのクラウドでも同じワークフロー(plan/apply)で扱えるか」を問われたら、プロバイダを差し替えるだけで実現できる。クラウドごとに実行やバイナリを分ける発想は誤り。", "eg": "海外旅行で言葉(操作の手順)はそのままでも、現地通貨(プロバイダ)を両替すればどの国でも買い物ができるのと同じ。"}, "terraform-associate-q3": {"point": "「望ましい最終状態を書き、差分の計算はツールに任せる」が宣言的の要点。手順を1行ずつ指定する・毎回全部作り直す・順序を必ず手動指定する、はいずれも命令的の特徴で誤り。", "eg": "レストランで「おまかせ」を頼むようなもの。仕上がり(最終状態)だけ伝えれば、何をどの順で用意するかは店側(ツール)が考える。"}, "terraform-associate-q4": {"point": "「プロバイダのバージョンを固定/制約する」ならterraformブロック内のrequired_providers。region等の接続設定やtfvars、backendの設定場所と混同しない。", "eg": "服のタグに「素材はコットン100%」と書いてあるように、部品そのものの仕様(バージョン)は部品表に明記する。どこで着るか(region)の話とは別の紙に書く。"}, "terraform-associate-q5": {"point": "「使ったプロバイダの版とハッシュを固定して再現性を保つ」なら依存ロックファイル(.terraform.lock.hcl)。現在の実リソース状態を保存するのはstate、変数値はtfvarsと役割が別。", "eg": "本の奥付に「第3版第2刷」と印刷されているようなもの。誰が手に取っても同じ版を参照できる控えであって、本の中身そのもの(state)ではない。"}, "terraform-associate-q6": {"point": "initは「準備」だけ。バックエンドの初期化とプロバイダ/モジュールの取得はinitの仕事、実インフラの作成やstateの削除はinitではしない。", "eg": "引っ越し前の荷造りと搬入路の確保のようなもの。まだ新居に家具は置いていない(実インフラはまだ作られていない)。"}, "terraform-associate-q7": {"point": "「プロバイダのプラグインはいつダウンロードされるか」と問われたらinit実行時。plan/apply/validateは取得済みの前提で動く。", "eg": "旅行前に必要な物を全部かばんに詰めておくようなもの。現地(plan/apply)に着いてから買い足しには行かない。"}, "terraform-associate-q8": {"point": "同一プロバイダを複数リージョンやアカウントで使い分けたいなら、providerにaliasを定義してリソース側で明示指定する。ディレクトリを完全に分けたり二重宣言したりcountで複製したりする必要はない。", "eg": "同じ人が「自宅用の名刺」と「会社用の名刺」を使い分けるようなもの。同じプロバイダに別名(alias)の設定を持たせて、場面ごとに指名して使う。"}, "terraform-associate-q9": {"point": "「なぜstateがあるか」と問われたら、構成と実リソースの対応を保持し差分計算に使うため。認証情報の暗号化や構文検証、依存関係の解決の話ではない。", "eg": "図書館の蔵書目録のようなもの。目録(state)があるから、どの本(リソース)がもう棚にあり、どれを新しく仕入れるべきかすぐ分かる。目録が無ければ棚を毎回全部数え直すしかない。"}, "terraform-associate-q10": {"point": "コアワークフローの順番を問われたら「構成を書き、initで初期化し、planで確認してから、applyで反映する」の順。applyが先に来たり、initが後ろに来たりする並びは誤り。", "eg": "料理番組の進行のようなもの。レシピを読む、材料と道具を揃える、仕上がりの写真(計画)を確認する、実際に作る、という順番を飛ばさない。"}, "terraform-associate-q11": {"point": "「構文や参照ミス、型不整合をローカルで検査」ならvalidate。書式を揃えるのはfmt、内容を表示するのはshow、stateを更新するのはrefreshで役割が違う。", "eg": "作文を提出する前に文法や誤字だけを見直す作業のようなもの。内容(実際に作るインフラ)が良いかどうかまでは判定しない。"}, "terraform-associate-q12": {"point": "「構成ファイルを標準の書式・スタイルに整形する」ならfmt。妥当性の検証はvalidate、変数の自動削除やstateの整形はfmtの仕事ではない。", "eg": "原稿の字下げや改行の位置を揃える校正のようなもの。文章の内容が正しいかどうかまでは見ない。"}, "terraform-associate-q13": {"point": "「planを実行すると実インフラが変更される」という文が出たら誤り。planは差分を見せるだけで、実際には何も変えない。", "eg": "レントゲン写真を撮るだけでは体は治らないようなもの。実際の治療(apply)をして初めて変化が起きる。"}, "terraform-associate-q14": {"point": "「リソースを1つだけ強制的に再作成したい」なら現行はapply -replace=ADDRESS。taintは非推奨、destroy -targetは削除のみで再作成しない、refresh -targetはstate更新のみで再作成しない。", "eg": "家電を1台だけ買い替えるようなもの。家全体を建て直す(destroy)わけでも、古い家電に印を貼るだけ(taintという今は使われなくなったやり方)でもなく、新しい交換依頼(-replace)を出す。"}, "terraform-associate-q15": {"point": "destroyの対象と問われたら、そのワークスペースの構成が管理する実リソース全部。stateファイルやプラグイン、.terraformディレクトリ自体の削除ではない。", "eg": "引っ越しで持ち物を全部処分するようなもの。処分するのは実際の家財(実リソース)であって、住所録のメモ(state)や引っ越し業者の道具(プラグイン)ではない。"}, "terraform-associate-q16": {"point": "「レビューした計画どおりに確定適用したい」なら plan -out=FILE の後 apply FILE。-outはplan側のオプションで、apply -outや存在しないフラグは誤り。", "eg": "見本の写真を撮っておいて、後でその写真どおりの品を注文するようなもの。途中で品物がすり替わらない。"}, "terraform-associate-q17": {"point": "「作成・管理する」ならresource、「既存情報を参照するだけ」ならdata。書き込み専用/読み取り専用が逆転した説明や、両者が同義だという説明、ローカル変数扱いはいずれも誤り。", "eg": "resourceは自分の名義で契約する部屋、dataは友人の家の住所を調べて地図に書き込むだけのようなもの。友人の家を勝手に改装(管理)はしない。"}, "terraform-associate-q18": {"point": "キーにハイフンを含むmapの参照は var.マップ名[\"キー\"] のブラケット記法を使う。ドット記法(var.map.key)はハイフン入りキーでは使えない。", "eg": "ホテルの部屋番号が「101-A」のようにハイフン入りだと、フロントで区切って言うのではなく、番号そのものをそのまま伝える必要があるのと同じ。"}, "terraform-associate-q19": {"point": "「名前付きで、属性ごとに型がバラバラなデータをまとめる」ならobject({...})。名前の無い順序だけの並びはtuple、全属性が同一型ならmap、リストで束ねるならlist(object(...))で、それぞれ別物。", "eg": "履歴書のように「氏名・年齢・住所」と項目名が決まっていて、それぞれ書く内容の型が違う書類がobject。項目名の無い箇条書きのメモがtuple。"}, "terraform-associate-q20": {"point": "for_eachに渡せるのはmapか文字列のset。listやnumberはそのままでは渡せず、listはtoset()などでset化してから使う。", "eg": "出席番号ではなく名前で呼ぶ点呼のようなもの。名前(キー)が一人ひとりに付いているmap/setだから、途中で誰かが抜けても他の人の呼び名は変わらない。"}, "terraform-associate-q21": {"point": "「countで作った途中の要素を削除する」と問われたら、以降のインデックスがずれて無関係なリソースまで再作成される。エラーで停止する・差分が生じない・stateが自動修復する、はいずれも誤り。", "eg": "背番号(1、2、3…)で座席が決まっている劇場で、途中の座席を撤去すると後ろの人が全員1つずつ前に詰めて座り直すことになるようなもの。名前で座席が決まっていれば(for_each)、そんな詰め直しは起きない。"}, "terraform-associate-q22": {"point": "1つのリソースの中にある可変個の「ネストブロック」をループ生成したいならdynamic。count/for_eachはリソースそのものの複製、provisionerは作成後のコマンド実行で、いずれも別物。", "eg": "履歴書1枚の中で「資格欄」を持っている資格の数だけ増やすようなもの。履歴書自体(リソース)を何枚も複製するわけではない。"}, "terraform-associate-q23": {"point": "入力変数そのものの範囲・形式をチェックしたいならvariableブロック内のvalidation。preconditionはリソース適用直前の前提条件、checkは継続的な監視、providerの設定引数とは役割が別。", "eg": "アンケート用紙に「年齢は0〜120の範囲で記入してください」という注意書きが付いているようなもの。回答者(入力値)がその場で弾かれる。"}, "terraform-associate-q24": {"point": "「適用前後の前提・結果条件をリソース側で宣言する」ならlifecycle内のprecondition/postcondition。入力値の検証はvariableのvalidation、版要件はrequired_version、秘匿はoutputのsensitiveで、それぞれ別物。", "eg": "手術前に本人確認や同意書を確認し(precondition)、手術後にバイタルが安定しているか確認する(postcondition)関門のようなもの。"}, "terraform-associate-q25": {"point": "checkブロックは、失敗しても警告に留まりapplyは止めない。「必ず失敗させて停止する」「入力の型を検証する」「削除を恒久的に禁止する」はいずれも別機能の説明で誤り。", "eg": "車のダッシュボードにある「そろそろオイル交換」の警告灯のようなもの。ランプが点いても車はそのまま走り続けられる。止まるべき異常(precondition失敗)とは扱いが違う。"}, "terraform-associate-q26": {"point": "「stateやplanに機密値を一切残さない」ならwrite-only引数かephemeralな値/リソース。sensitive=trueは画面表示を隠すだけで平文のまま残り、-varでの受け渡しも保存自体は防げない。", "eg": "一度読んだら残らない伝言(ephemeral)や、受け取るだけで控えを取らない窓口(write-only)のようなもの。黒塗りにした手紙(sensitive)は、局に保管されている元の手紙自体はそのまま残っている。"}, "terraform-associate-q27": {"point": "「sensitive=trueを付けた変数はstateに保存されない」という文が出たら誤り。sensitiveは表示を隠すだけで、stateの中身は平文のまま残る。", "eg": "テレビ放送でモザイクをかけたのは画面の映像だけで、局に保管されている元の映像データ(state)はモザイク無しのまま残っているようなもの。"}, "terraform-associate-q28": {"point": "参照(A.idをBが使う等)が無いのに順序を保証したい場合だけdepends_on。lifecycleは作成/削除時の振る舞い、for_eachは反復生成、provisionerは実行系で、いずれも別物。", "eg": "先に着替えを済ませておかないとシャワーの順番が意味をなさない、というように見た目には無関係そうでも実は順番が要る間柄に、あえて「先にこっち」と札を付けておくようなもの。"}, "terraform-associate-q29": {"point": "モジュールのversion引数が効くのはTerraformレジストリ(公開/HCPプライベート)経由の場合だけ。Git参照はref引数で版を指定し、ローカルパスやHTTP URLにはversionという概念自体が無い。", "eg": "通販サイトで「型番と版」を指定して注文できるのは正規販売店(レジストリ)経由のときだけ。知人から直接譲ってもらう(Git/ローカル)場合は、相手が持っている物がそのまま渡されるだけ。"}, "terraform-associate-q30": {"point": "子モジュールとのやり取りは「渡すのはinput variables、受け取るのはoutput values」。stateの直接共有やprovider経由、data経由での受け渡しは正規の方法ではない。", "eg": "窓口の申込用紙(入力変数)に必要事項を書いて出し、後で受け取り票(output)を渡されるやり取りのようなもの。裏口(state共有)から直接やり取りするのとは違う。"}, "terraform-associate-q31": {"point": "モジュール内で宣言した変数は「そのモジュールの中だけ」で有効。親モジュールへ自動で継承されたり、グローバル共有されたり、環境変数として自動公開されたりはしない。境界をまたぐ時は明示的に渡す。", "eg": "社内の一部署だけで通じる合言葉のようなもの。他の部署に伝えたければ、わざわざ口頭で伝える(明示的に渡す)必要がある。"}, "terraform-associate-q32": {"point": "公開レジストリのモジュールはsource = \"namespace/name/provider\" の3段スラッシュ表記。生のURLや独自スキームでの指定は無効。", "eg": "書籍のISBNのように、決まった区切りと並びのコードで指定するようなもの。自由な言い回しのURLでは通じない。"}, "terraform-associate-q33": {"point": "レジストリモジュールを安定運用するなら ~> 3.1 のような悲観的制約で上限を区切る。latestを指す・上限を設けない・制約自体を書かない、はいずれも破壊的更新を招く。", "eg": "「同じシリーズの新刊は買うが、シリーズが変わったら買わない」という予約購読のルールのようなもの。"}, "terraform-associate-q34": {"point": "リモートバックエンドの設定はterraformブロック内のbackend \"s3\" { ... }。providerの引数でも独立したresourceでもなく、terraform_remote_stateは他stateの出力を読むためのdataであって設定場所ではない。", "eg": "アパートの契約書にある「管理会社」欄に保管方式を書き込むようなもの。入居者側(provider)の欄に書くものではない。"}, "terraform-associate-q35": {"point": "state lockingの目的は同時実行によるstateの破損防止。暗号化・差分計算の高速化・IAM権限管理とは別の話。", "eg": "会議室のドアにかかった「使用中」の札のようなもの。誰かが使っている間は他の人が同時に入って書類を書き換えられないようにする。"}, "terraform-associate-q36": {"point": "追加リソース無しでネイティブにロックを持つのはHCP TerraformとGCSバックエンド。ローカル単体運用や-lock=falseはロックが効かない、または無効化される。", "eg": "最初からオートロックが付いている宿泊施設(HCP/GCS)と、鍵を別に買い足す必要がある部屋や鍵を外したままの部屋(ローカル単体/-lock=false)の違いのようなもの。"}, "terraform-associate-q37": {"point": "手動変更によるドリフトを検出したいならplanまたはrefresh-onlyで構成と実態の差分を見る。fmtは書式整形、validateは構文検証、importは新規取り込みで、いずれもドリフト検出ではない。", "eg": "棚卸しで、帳簿に書かれた数と実際に倉庫にある在庫数を数え直して照らし合わせる作業のようなもの。"}, "terraform-associate-q38": {"point": "実体は変えずにstate上のアドレスだけ変更(リファクタ)したいならmovedブロック。removedは管理から外す、importは新規取り込み、prevent_destroyは削除防止で、いずれも別物。", "eg": "結婚して名字が変わっても本人(実リソース)は同じ人であるように、呼び名(アドレス)だけを更新して作り直しを避けるようなもの。"}, "terraform-associate-q39": {"point": "実インフラは残したままTerraform管理からだけ外したいならremovedブロック。destroyは実体ごと削除、movedはアドレス変更、create_before_destroyは置換時の順序制御で、いずれも別物。", "eg": "レンタル倉庫の契約を解除しても、荷物(実リソース)自体はそのまま倉庫に残るようなもの。管理する人がいなくなるだけで物は消えない。"}, "terraform-associate-q40": {"point": "実態に合わせてstateだけ更新し、インフラ自体は変更しないならrefresh-onlyモード。実インフラの変更は通常のapply、state削除や計画の保存とは別の話。", "eg": "実際の財布の中身に合わせて家計簿を書き直すようなもの。財布の中身(実インフラ)自体はそれで変わらない。"}, "terraform-associate-q41": {"point": "既存の実リソースを宣言的に取り込むならimportブロック(toとidを記述)。movedはアドレス変更、state pushはstate全体の上書きで危険、dataは参照のみで取り込みではない。", "eg": "すでにそこに住んでいる人を、あとから住民票に登録する手続きのようなもの。人(実リソース)自体は最初から存在している。"}, "terraform-associate-q42": {"point": "importブロックと組み合わせて構成(HCL)を自動生成するなら plan -generate-config-out=FILE。showは表示、applyは適用、init -upgradeはプロバイダ更新で、いずれも生成機能ではない。", "eg": "中古住宅を内見したときの寸法から、図面の下書きを自動で起こしてもらうようなもの。細部はあとで手直しする。"}, "terraform-associate-q43": {"point": "state内の管理対象アドレス一覧を見るならstate list。1件の詳細はstate show、出力値の表示はoutput、全体構造の表示はshow -jsonで、いずれも別物。", "eg": "図書館の蔵書検索で、まず書名の一覧(state list)を出し、その中の1冊を選んで詳細ページ(state show)を開くという2段階の探し方のようなもの。"}, "terraform-associate-q44": {"point": "state内の特定リソース1件の属性詳細を見るならstate show <ADDRESS>。listは一覧のみ、outputは出力値、planは差分表示で、いずれも別物。", "eg": "名刺入れの中から1枚を取り出して、その人の連絡先を確認するようなもの。名刺入れ全体を見渡す(list)のとは段階が違う。"}, "terraform-associate-q45": {"point": "詳細ログを有効化する環境変数はTF_LOG。TF_DEBUG・TERRAFORM_LOG・LOG_LEVELという変数は存在しない。", "eg": "レコーダーの「詳しく録音する」ボタンの正確な名前を知らないと押せないのと同じで、似た名前のボタンをいくら探しても機能は動かない。"}, "terraform-associate-q46": {"point": "詳細ログの出力先ファイルを指定する環境変数はTF_LOG_PATH。TF_LOG_FILE・TF_OUT・TF_LOG_DESTは存在せず、有効化するTF_LOGとセットで使う。", "eg": "留守番電話の「メッセージの保存先」を指定するボタンのようなもの。録音するかどうかのスイッチ(TF_LOG)とは別に、どこに残すかを決める。"}, "terraform-associate-q47": {"point": "環境やチーム単位で複数ワークスペースをグループ化する上位単位はプロジェクト(Projects)。変数セットは値の共有、run triggersは連鎖実行の機能で、整理の単位そのものではない。", "eg": "会社の書類棚で、部署ごとにフォルダを分けて整理するようなもの。フォルダ(プロジェクト)は書類(ワークスペース)を束ねる箱の役割。"}, "terraform-associate-q48": {"point": "HCP Terraformでのrun起動方式はVCS駆動とCLI駆動(とAPI駆動)。手元でstateを手動アップロードしたり、cronでローカルバイナリを定期実行したりするのは正規の起動方式ではない。", "eg": "受付が「予約サイトからの申込(VCS)」と「窓口での直接申込(CLI)」を正式なルートとして受け付けるようなもの。裏口から勝手に入る(state手動投入)のは正規のルートではない。"}, "terraform-associate-q49": {"point": "複数ワークスペースに共通の変数を一元管理して適用するならVariable sets。tfvarsを各所に複製するのは重複管理、run triggersは実行連鎖、projectsは整理単位で、それぞれ別物。", "eg": "本社が全支店に一斉配布する共通マニュアルのようなもの。支店ごとに個別コピーを手作りする(tfvars複製)と、更新のたびに配り直しが漏れる。"}, "terraform-associate-q50": {"point": "あるワークスペースのapply成功を別ワークスペースの実行の引き金にしたいならRun triggers。Variable setsは変数共有、depends_onは単一構成内の依存、webhook直設定は正規手段ではない。", "eg": "リレー競走のバトンパスのようなもの。前の走者(上流ワークスペース)が走り終えたら、次の走者(下流ワークスペース)が自動でスタートする。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'terraform-associate')
  AND q.explanation_data IS NOT NULL;

-- terraform-associate-b
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"terraform-associate-b-q1": {"point": "同じ構成に対する2回目以降のapplyは、差分が無ければ「変更なし」で何も起きない。実行回数では結果は変わらない。", "eg": "目覚まし時計をすでに7時に合わせてあるのに、また7時にセットし直しても何も変わらないのと同じ。"}, "terraform-associate-b-q2": {"point": "「インフラそのものを用意する話」か「用意した上のOS設定の話」かで、Terraformか構成管理ツールかを見分ける。クラウド/オンプレやエージェントの有無は分岐点ではない。", "eg": "オフィスを借りるとき、物件そのものを契約するのは不動産屋、借りた後にデスクや配線を整えるのは総務担当、という役割分担に近い。"}, "terraform-associate-b-q3": {"point": "「差分をレビューでき、履歴を追え、前の版へ戻せるか」がバージョン管理の利点。暗号化や実行速度の話ではない。", "eg": "作文を鉛筆で直すとき、消しゴムで消さずに二重線を引いて直した跡を残しておくと、誰が後から読んでも「いつ・どこを・なぜ直したか」を辿れて、前の書き方にも戻せる。"}, "terraform-associate-b-q4": {"point": "書いた桁数がそのまま許容範囲の天井を決める。~> 4.2.0 なら一番右の桁(パッチ)だけが動き4.2.xに収まる。", "eg": "値引き交渉で「1の位の端数はまけてよいが、10の位は変えない」と言われたら、108円は109円にはなっても、110円にはならないのと同じ感覚。"}, "terraform-associate-b-q5": {"point": "「CLI本体の話」か「プロバイダの話」かで required_version と required_providers を見分ける。同じ terraform ブロック内でも対象が違う。", "eg": "スマホ本体のOSの版(iOS17以上)を指定する欄と、入れるアプリの版を指定する欄が別々になっているのと同じ。"}, "terraform-associate-b-q6": {"point": "普通のinitは前回の記録どおりに入れるだけ。制約の範囲でより新しい版を取りに行きたいなら -upgrade を明示する。", "eg": "図書館で「前と同じ版を返して」と言えば同じ版が来るが、「新しい版が出ていたら借り直して」と頼まないと版は上がらない。"}, "terraform-associate-b-q7": {"point": "GitHubのパスに見えても、hashicorp/aws は既定レジストリのホスト部分(registry.terraform.io/)が省略された住所だと気づけるかが決め手。", "eg": "「渋谷区」とだけ言っても「東京都渋谷区」だと伝わるのと同じで、既定の上位(都・県、あるいは既定レジストリ)は省略してよい。"}, "terraform-associate-b-q8": {"point": "「誰が要求しているか」を一覧したいなら terraform providers。「今入っている版」だけならversion。", "eg": "名刺交換の場で「あなたを紹介してくれたのは誰ですか」と辿っていく家系図のようなもの。"}, "terraform-associate-b-q9": {"point": "stateは「構成(欲しいもの)」と「実物(今あるもの)」を結ぶ台帳。HCL自体・プラグイン・認証情報はそこに入らない。", "eg": "宅配便の伝票が「注文した品物」と「実際に届いた荷物」を紐づけているのと同じ役割。"}, "terraform-associate-b-q10": {"point": "CIで差分の有無に応じて分岐したいなら -detailed-exitcode。既定の終了コードは成功か失敗かの2値しか返らない。", "eg": "テストの結果を「合格・不合格」の2択ではなく、「満点・部分点・0点」の3段階で返してもらうよう頼むイメージ。"}, "terraform-associate-b-q11": {"point": "planもapplyも、まず実インフラの今の状態を読みに行ってから差分を計算する。そのうえで実物を変えるのはapplyだけ。", "eg": "買い物リストを作る前に、まず冷蔵庫の中身を確認するようなもの。確認するだけなら中身は減らないが、実際に使えば(apply)減る。"}, "terraform-associate-b-q12": {"point": "-target は実在するが、常用ではなく緊急時の例外的な手段。-only や -exclude というフラグは存在しない。", "eg": "非常口は実在するが、毎日の通勤にはふだんの正面玄関を使い、非常口は緊急時にしか使わないのと同じ位置づけ。"}, "terraform-associate-b-q13": {"point": "実インフラに一切触れず式や関数の結果だけ試したいなら terraform console。", "eg": "買い物の前に電卓で「これで合計いくらになるか」だけ先に確かめておくのと同じ。"}, "terraform-associate-b-q14": {"point": "他のツールへ機械的に値を渡したいなら terraform output -json。人向けの表示を切り出すのは書式が変わると壊れる。", "eg": "レシートを手で書き写すのではなく、レシートのQRコードをそのまま読み取ってデータで受け取るようなもの。"}, "terraform-associate-b-q15": {"point": "validate はリモートに一切問い合わせず、構文と構成内部の整合だけを検査する。実インフラの状態や認証情報の有効性は範囲外。", "eg": "手紙を投函する前に、机の上で宛名や便箋の書式だけを確認するようなもの。ポストに実際に届くかどうかまでは確認しない。"}, "terraform-associate-b-q16": {"point": "destroy は apply -destroy の別名で、削除も「計画を作って適用する」いつもの流れに乗る。state の扱いも確認の有無も両者で変わらない。", "eg": "引っ越しの依頼で「荷物を運んでください」も「全部処分してください」も、同じ受付窓口に同じ様式の依頼書を出すのと同じ。"}, "terraform-associate-b-q17": {"point": "外から値を渡したい変数はvariable、渡す必要のない構成内だけの中間値はlocals、で見分ける。", "eg": "家計簿で、家族から渡されたお小遣いの金額(variable)と、自分でレシートを足し合わせて出した合計(locals)は別物として扱うのと同じ。"}, "terraform-associate-b-q18": {"point": "HCLに if 文は無い。分岐は「条件 ? 真の値 : 偽の値」という1種類の式だけで書く。", "eg": "レストランの注文票で「Aランチ、それともBランチ」と一言で選ばせるようなもの。手順書のように「まず確認して、次に…」とは書かない。"}, "terraform-associate-b-q19": {"point": "複数リソースから属性をまとめて取り出すには、まずリソース名の直後に[*]を置き、その後ろで属性名をつなげる。", "eg": "「クラス全員の身長」とは言うが「身長のクラス全員」とは言わない、日本語の語順と同じで、先に対象(複数)、後に属性を置く。"}, "terraform-associate-b-q20": {"point": "「マップから」「キーで引く」「無ければ既定値」の3つが揃う場面はlookup一択。", "eg": "辞書で単語を引いて、載っていなければ余白に「不明」と書いておく付箋のようなもの。"}, "terraform-associate-b-q21": {"point": "外部ファイルの中身に変数を埋め込んで置き換えたいならtemplatefile。file はそのまま読むだけで置換はしない。", "eg": "名前欄が空欄の招待状のひな形に、招く相手の名前を書き込んで渡すのがtemplatefile。ひな形をそのままコピーして渡すだけならfile。"}, "terraform-associate-b-q22": {"point": "リソース間の順序は「属性を参照しているか」で決まる。記述順やアルファベット順は関係ない。", "eg": "手紙の宛名を書くには、先に宛先の住所を知っている必要がある。書く順番ではなく、必要としている(参照している)かどうかで前後が決まる。"}, "terraform-associate-b-q23": {"point": "設定変更のたびに置き換えが起き、その間のダウンタイムを避けたいなら create_before_destroy = true。既定は壊してから作る順序。", "eg": "橋を架け替えるとき、古い橋を先に壊すとその間渡れなくなるが、新しい橋を先に架けてから古い橋を壊せば、常にどちらかの橋を渡れる。"}, "terraform-associate-b-q24": {"point": "誤って破棄されると困るリソースには prevent_destroy = true。破棄を含む計画そのものをエラーで止める。", "eg": "大事な書類の入った箱に「シュレッダー禁止」の付箋を貼っておくと、誤って処分しようとした手が止まるのと同じ。"}, "terraform-associate-b-q25": {"point": "外部の仕組みが正当に変える属性の差分を、毎回戻さず無視したいなら ignore_changes にその属性を指定する。", "eg": "子どもが自分の部屋を自分の判断で模様替えするのを、親が毎回「元に戻して」と言わずに放っておくのと同じ。"}, "terraform-associate-b-q26": {"point": "変数はその場で明示的に指定したものほど強い。tfvarsとコマンドラインが両方あれば、最後に効くコマンドラインの-var/-var-fileが勝つ。", "eg": "待ち合わせ場所を事前にLINEで決めていても、当日「やっぱりここに変更」と直接言われたら、直近の一言が優先されるのと同じ。"}, "terraform-associate-b-q27": {"point": "オブジェクト型の一部の属性だけを任意にしたいなら型の中で optional(型, 既定値)。nullableは変数全体にnullを許すかどうかの話で別物。", "eg": "申込書の「電話番号は空欄可」のように一部の欄だけ任意にするのと、書類の提出自体を任意にするのは別の話であるのと同じ。"}, "terraform-associate-b-q28": {"point": "sensitive = true が隠すのはCLI表示だけ。stateファイルの中身は平文のまま保存される。", "eg": "手紙の封筒に「開封注意」と書いても、中の便箋の文字が自動で暗号文に変わるわけではないのと同じ。"}, "terraform-associate-b-q29": {"point": "同じモジュールを設定ごとに繰り返し呼びたいなら、moduleブロックにもcount/for_eachをリソースと同じ感覚で使える。", "eg": "コピー機で1枚ずつ手差しするのではなく、「この原稿を3部」とまとめて指定するのと同じ。"}, "terraform-associate-b-q30": {"point": "プロバイダを渡す先がresourceなら単数のprovider、moduleなら複数形のprovidersでマップを渡す、と単数複数で見分ける。", "eg": "部署異動の辞令のように「このモジュールの中ではawsという名前で、実体は親のaws.tokyoを使う」という対応表を渡すイメージ。"}, "terraform-associate-b-q31": {"point": "レジストリ由来のモジュールはversion引数、Git由来のモジュールはsourceの中の?ref=で版を指定する、と出所で使い分ける。", "eg": "書店(レジストリ)で本を注文するなら「第3版をください」と版数だけ伝えればよいが、知人の家(Gitリポジトリ)から借りるなら「あの棚のあの本」と場所そのものを指定する必要があるのと同じ。"}, "terraform-associate-b-q32": {"point": "子モジュールの出力を読むときは module.<呼び出し名>.<出力名> と直接指す。式の中に output という語は挟まない。", "eg": "社内で人を呼ぶとき「営業部の田中さん」とは言うが、「営業部の役職の田中さん」のように役職名を挟んで呼ばないのと同じ。"}, "terraform-associate-b-q33": {"point": "既定値の無い変数は必須。呼び出し側が渡し忘れると入力を求められ、非対話環境ではエラーになる。親からの自動継承は無い。", "eg": "誕生日プレゼントを頼まれて希望を聞かなかったら「何が欲しいですか」と聞き返されるだけで、親の好みを勝手に継承したりはしないのと同じ。"}, "terraform-associate-b-q34": {"point": "backendブロックを何も書かなくても、既定のローカルバックエンドが黙って使われ、作業ディレクトリにstateファイルができる。", "eg": "送り先を指定せず荷物を出しても、宅配業者が自動的に「近くの営業所」に保管しておいてくれるようなもの。何も指定しない=何も起きない、ではない。"}, "terraform-associate-b-q35": {"point": "backendブロックの中には変数や式を書けない。共通部分だけ構成に書き、環境ごとに違う部分は init -backend-config で実行時に渡す。", "eg": "契約書のひな形に会社名は事前に印刷しておき、日付だけは契約当日にその場で手書きするようなもの。"}, "terraform-associate-b-q36": {"point": "既存のstateを新しいバックエンドへ運びたいなら -migrate-state。-reconfigure は荷物(state)を運ばず設定だけ入れ替える。", "eg": "引っ越しで、家財ごと運んでもらう引っ越し業者(-migrate-state)と、住所変更届だけ出して家財は現地に残す場合(-reconfigure)の違い。"}, "terraform-associate-b-q37": {"point": "別stateの値がほしいときは、相手のstateを直接覗くのではなく、相手がoutputとして公開した値だけをterraform_remote_stateで受け取る。", "eg": "隣の家の中を覗くのではなく、玄関先の郵便受けに置いてもらった手紙だけを受け取るようなもの。"}, "terraform-associate-b-q38": {"point": "「管理から外したいだけで実物は残したい」ならterraform state rm。台帳から行を消すだけで実リソースには触れない。", "eg": "図書館の貸出台帳から自分の名前を消しても、借りていた本自体が消えてなくなるわけではないのと同じ。"}, "terraform-associate-b-q39": {"point": "残留したstateロックは、エラーに表示されるロックIDをterraform force-unlockに渡して正規に外す。-lock=falseは守り自体を無効化する迂回で避ける。", "eg": "鍵をなくして家に入れないとき、鍵屋を呼んで正規に開けてもらうのと、鍵ごと壊して誰でも入れる状態にしてしまうのとの違い。"}, "terraform-associate-b-q40": {"point": "stateの中身を守るのはsensitiveではなくバックエンド側の暗号化とアクセス制御。sensitiveを付けていても値は平文で入りうる。", "eg": "手紙の封筒に「開封注意」のシールを貼っても、中の便箋の文字は暗号文にならない。中身を本当に守るのは金庫(バックエンドの暗号化)の役目。"}, "terraform-associate-b-q41": {"point": "CLIワークスペースで分かれるのはstateだけ。構成もバックエンドも共通のまま。HCP Terraformのワークスペースとは同名の別概念。", "eg": "同じ台本(構成)を使って、平日公演と休日公演で配役表(state)だけ差し替えるようなもの。舞台(バックエンド)や台本自体は共通。"}, "terraform-associate-b-q42": {"point": "リソース間の依存関係を図として見たいならterraform graph。DOT形式で出力される。", "eg": "誰が誰を親にしているかを線でつないでいく家系図のようなもの。"}, "terraform-associate-b-q43": {"point": "すでに保存した計画ファイルを機械的に読みたいならterraform show -json。plan -jsonはその場で新しく計画を作りながら流すもので、保存済みファイルの検査には使わない。", "eg": "すでに撮った写真をスキャンして後から解析するのと、これから写真を撮りながら同時に解析するのは別の作業であるのと同じ。"}, "terraform-associate-b-q44": {"point": "TF_LOGのレベルはTRACE > DEBUG > INFO > WARN > ERRORの順に詳細。VERBOSEというレベルは存在しない。", "eg": "望遠鏡の倍率を上げるほど遠くの細部まで見えるように、TRACEにすると内部のやりとりまで細かく見える。"}, "terraform-associate-b-q45": {"point": "CLIのterraform importを使う前に、取り込み先のリソースブロックを構成へあらかじめ書いておく。importはstateへの登録だけで構成は生成しない。", "eg": "転校生を出席簿に加える前に、教室に机を用意しておかないと、名簿には載っても座る場所が無いのと同じ。"}, "terraform-associate-b-q46": {"point": "プロビジョナーは「他に手段が無いときの最後の手段」という位置づけ。可能ならプロバイダの機能で済ませる。", "eg": "説明書通りに家具を組み立てるのが基本だが、どうしても合わない部品だけ最後にドライバーで無理やり調整するようなもの。日常的なやり方ではない。"}, "terraform-associate-b-q47": {"point": "cloudブロックを設定したうえで、実行の起点が手元のCLIならCLI駆動ワークフロー。起点がリポジトリへのpushならVCS駆動。", "eg": "リモートワークの社員が、自分のパソコンから「実行開始」のボタンを押すと、作業自体は会社のサーバー側で行われるようなもの。"}, "terraform-associate-b-q48": {"point": "「applyの前に組織の規則を自動で強制したい」ならSentinelまたはOPAによるポリシー適用。planの結果を機械が審査してから先へ進める。", "eg": "提出前の書類を、上司の目視チェックではなく、システムが「必須項目が埋まっているか」を自動で審査して不備なら突き返すようなもの。"}, "terraform-associate-b-q49": {"point": "長期のアクセスキーを保存せずに済ませたいなら動的プロバイダ認証情報。実行のたびに短命な資格情報を借りる仕組みで、隠すのではなくそもそも持たない。", "eg": "家の合鍵を友人に預けっぱなしにするのではなく、来るたびにその日限りの合鍵を発行してもらうようなもの。"}, "terraform-associate-b-q50": {"point": "ワークスペースを束ねて、その単位でチーム権限も付けたいならプロジェクト。タグは絞り込みの目印にはなるが権限の単位にはならない。", "eg": "会社の組織図で、個々の社員(ワークスペース)を部署(プロジェクト)にまとめて、部署ごとにアクセス権限を設定するようなもの。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'terraform-associate-b')
  AND q.explanation_data IS NOT NULL;

COMMIT;
